// Idle auto-recenter (added feature, v39).
//
// Direct movement mode is relative: the cursor ends up wherever the sum of
// all head motion has carried it. Camera drift and small posture changes
// accumulate into that sum, so after a while "head facing straight ahead"
// no longer means "cursor at the middle" - the cursor ends up biased to one
// side. The recenter-on-enable setting fixes this once per session; this
// module repeats it automatically: when no cursor movement (and no click)
// has happened for a configurable number of seconds, the cursor glides back
// to the screen center over a short animation, and that head pose becomes
// the new center.
//
// Pure logic, exported for testing: `applyAutoRecenter` is a state machine
// driven once per frame with the current cursor/activity values; it returns
// where the cursor should be this frame plus state transitions. The frame
// loop in tracky-mouse.js owns everything impure (the real cursor, the tilt
// neutral, the center point).

export const AUTO_RECENTER_DURATION_MS = 600; // glide duration

const easeInOut = (t) => t * t * (3 - 2 * t); // smoothstep

/**
 * One frame of the idle auto-recenter state machine.
 * @param state {{ idleSince: number|null, anim: object|null }} mutable state,
 *   created once (e.g. `createAutoRecenterState()`).
 * @param p {{
 *   mouseX, mouseY, // current cursor position (virtual-desktop px)
 *   deltaX, deltaY, // this frame's head-driven movement, 0 = head still
 *   activity, // boolean: anything happened that should reset the idle timer
 *     (buttons held, recent click, clutch pin, calibration, ...)
 *   idleSeconds, // setting: seconds of stillness before recentering (0 = off)
 *   now, // performance.now()
 *   target, // {x, y}|null: the screen center to glide to (null = unknown)
 * }}
 * @returns {{
 *   mouseX, mouseY, // where the cursor should be this frame
 *   animating, // true while the glide runs (caller skips normal movement)
 *   resetTilt, // true on the frame the glide completes: treat the head pose
 *              // now as the new "facing the center" pose
 * }}
 */
export function applyAutoRecenter(state, {
	mouseX, mouseY,
	deltaX = 0, deltaY = 0,
	activity = false,
	idleSeconds = 0,
	now,
	target = null,
}) {
	const moved = deltaX !== 0 || deltaY !== 0;
	const result = { mouseX, mouseY, animating: false, resetTilt: false };

	// Off, or not running (paused / initializing): forget any pending state
	// so re-enabling starts a fresh idle count instead of instantly recentering.
	if (!idleSeconds || idleSeconds <= 0) {
		state.idleSince = null;
		state.anim = null;
		return result;
	}
	if (moved || activity) {
		state.idleSince = null;
		state.anim = null;
		return result;
	}

	// Glide in progress: ease toward the target; head motion or a click
	// cancels it (handled above - `moved`/`activity` clears state.anim).
	if (state.anim) {
		const t = Math.min(1, (now - state.anim.start) / AUTO_RECENTER_DURATION_MS);
		const ease = easeInOut(t);
		result.mouseX = state.anim.fromX + (state.anim.toX - state.anim.fromX) * ease;
		result.mouseY = state.anim.fromY + (state.anim.toY - state.anim.fromY) * ease;
		result.animating = true;
		if (t >= 1) {
			result.mouseX = state.anim.toX;
			result.mouseY = state.anim.toY;
			result.animating = false;
			result.resetTilt = true;
			state.anim = null;
			state.idleSince = null;
		}
		return result;
	}

	// Counting stillness.
	if (state.idleSince === null) {
		state.idleSince = now;
		return result;
	}
	const stillForMs = now - state.idleSince;
	if (stillForMs < idleSeconds * 1000) {
		return result;
	}
	// Long enough - start gliding, unless the target is unknown or the
	// cursor is already (almost) there.
	if (!target || (Math.hypot(target.x - mouseX, target.y - mouseY) < 40)) {
		state.idleSince = now; // try again after another idle period
		return result;
	}
	state.anim = { fromX: mouseX, fromY: mouseY, toX: target.x, toY: target.y, start: now };
	return result;
}

export function createAutoRecenterState() {
	return { idleSince: null, anim: null };
}
